# openjiuwen 代码节点：Excel 导入（import-excel）
# 节点类型 jiuwen.code，本地执行。平台调用 main(args) -> dict
#
# 用户在工作流对话上传原油评价 Excel（.xls/.xlsx），Start 节点定义 file 入参，
# 文件进 OBS，本节点拿到签名 URL → 下载 → pandas 解析 → 写 6 张 PG 表。
#
# 入参（Start 节点定义）：
#   file_url     String 必填 —— 上传文件的 OBS 签名 URL（Start 的 file 入参传下来）
#   crude_name   String 可选 —— 用户指定原油名（优先于封面解析）
#   sample_date  String 可选 —— YYYYMMDD（优先于封面）
#   sample_point String 可选 —— 采样点（优先于封面）
# 出参：{"markdown": 导入结果, "crude_name", "sample_date", "sample_point"}
#
# 依赖：pandas（读 .xls/.xlsx）、requests（下载）、psycopg2（写库）——平台 venv 均有。
# 弃用 ChromaDB：文字描述只写 PG text_description 表。

import io as _io
import re
import datetime
import json
import os

import pandas as pd

SIDELINE_CUTS = {
    "石脑油": {"start": 0, "end": 180, "label": "初馏点~180℃"},
    "常一线": {"start": 180, "end": 220, "label": "180℃~220℃"},
    "常二线": {"start": 220, "end": 300, "label": "220℃~300℃"},
    "常三线": {"start": 300, "end": 370, "label": "300℃~370℃"},
    "减一线": {"start": 370, "end": 395, "label": "370℃~395℃"},
    "减二线": {"start": 395, "end": 450, "label": "395℃~450℃"},
    "减三线": {"start": 450, "end": 500, "label": "450℃~500℃"},
    "减四线": {"start": 500, "end": 540, "label": "500℃~540℃"},
    "渣油": {"start": 540, "end": 9999, "label": ">540℃"},
}

def _nrows(df):
    return df.shape[0] if df is not None else 0


def _ncols(df):
    return df.shape[1] if df is not None else 0


def _cell(df, r, c):
    """返回归一化后的单元格值：NaN/None → ''，datetime 原样返回，其余原样。

    对应 xlrd sh.cell(r,c).value：xlrd 空为 ''、数字为 float、错误单元格(ctype5)
    在 pandas 里都是 NaN → 这里统一成 ''。
    """
    if df is None or r >= df.shape[0] or c >= df.shape[1]:
        return ""
    v = df.iat[r, c]
    if v is None:
        return ""
    if isinstance(v, float) and pd.isna(v):
        return ""
    # pandas 可能给 numpy 标量，转成 python 原生
    try:
        if pd.isna(v):
            return ""
    except (TypeError, ValueError):
        pass
    return v


def _is_datetime(v):
    return isinstance(v, (datetime.datetime, datetime.date, pd.Timestamp))


def _get_sheet(sheets, *names):
    """按名取 sheet DataFrame，全不命中返回 None。"""
    for n in names:
        if n in sheets:
            return sheets[n]
    return None


def _safe_float(df, r, c):
    if c is None:
        return None
    try:
        v = _cell(df, r, c)
        if v == "" or v is None or str(v).strip() in ["", "-", "--"]:
            return None
        return float(v)
    except Exception:
        return None


def _safe_str(df, r, c):
    try:
        v = _cell(df, r, c)
        if v is None or str(v).strip() in ["", "-", "--"]:
            return None
        return str(v).strip()
    except Exception:
        return None


def _parse_date_to_yyyymmdd(date_str):
    """YYYY/MM/DD | YYYY-MM-DD | YYYY年MM月DD日 | YYYYMMDD → YYYYMMDD。"""
    m = re.match(r'(\d{4})[/\-年](\d{1,2})[/\-月](\d{1,2})', date_str)
    if m:
        y, mo, d = m.group(1), int(m.group(2)), int(m.group(3))
        return f"{y}{mo:02d}{d:02d}"
    m = re.match(r'^(\d{8})$', date_str.replace(' ', ''))
    if m:
        return m.group(1)
    return ""


# ── 封面 ────────────────────────────────────────────────────────────
def parse_cover_sheet(sheets):
    """解析封面，提取 crude_name / sample_point / sample_date。"""
    result = {"crude_name": "", "sample_point": "", "sample_date": ""}
    sh = _get_sheet(sheets, "封面")
    if sh is None:
        # 兜底：第一个 sheet
        vals = list(sheets.values())
        if not vals:
            return result
        sh = vals[0]

    nrows, ncols = _nrows(sh), _ncols(sh)
    for r in range(min(80, nrows)):
        row_texts = {}
        for c in range(min(ncols, 15)):
            v = _cell(sh, r, c)
            if v != "" and str(v).strip():
                row_texts[c] = str(v).strip()

        label_col = None
        for c, text in row_texts.items():
            if "原油名称" in text:
                label_col = c
                break

        if label_col is not None:
            raw = ""
            if ncols > 2:
                v = _cell(sh, r, 2)
                raw = str(v).strip() if v != "" and str(v).strip() else ""
            if not raw:
                for c in range(label_col + 1, min(ncols, label_col + 5)):
                    v = _cell(sh, r, c)
                    if v != "" and str(v).strip():
                        raw = str(v).strip()
                        break
            if raw:
                m = re.match(r'^(.+?)[（(](.+?)[)）]\s*$', raw)
                if m:
                    result["crude_name"] = m.group(1).strip()
                    result["sample_point"] = m.group(2).strip()
                else:
                    result["crude_name"] = raw
            continue

        for c, text in row_texts.items():
            if "采样日期" in text:
                date_raw = ""
                cellv = ""
                if ncols > 2:
                    cellv = _cell(sh, r, 2)
                    date_raw = str(cellv).strip() if cellv != "" and str(cellv).strip() else ""
                if not date_raw:
                    for dc in range(c + 1, min(ncols, c + 5)):
                        cellv = _cell(sh, r, dc)
                        if cellv != "" and str(cellv).strip():
                            date_raw = str(cellv).strip()
                            break
                if date_raw:
                    # pandas 把日期读成 datetime，直接格式化；否则走字符串解析
                    if _is_datetime(cellv):
                        try:
                            result["sample_date"] = cellv.strftime("%Y%m%d")
                        except Exception:
                            result["sample_date"] = _parse_date_to_yyyymmdd(date_raw)
                    else:
                        result["sample_date"] = _parse_date_to_yyyymmdd(date_raw)
                break

    return result


# ── 实沸点 ──────────────────────────────────────────────────────────
def parse_distillation_sheet(sheets, crude_name):
    """解析实沸点，兼容硬编码列号 + 自动检测表头两种格式。"""
    sh = _get_sheet(sheets, "实沸点", "实沸点蒸馏")
    if sh is None:
        return []

    nrows, ncols = _nrows(sh), _ncols(sh)
    rows = []

    # 方案一：硬编码列号（标准格式：行0标题, 行1-2表头, 行3+数据）
    if nrows > 3:
        first_val = str(_cell(sh, 3, 0)).strip()
        if first_val and (first_val[0].isdigit() or first_val[0] in '<>'):
            for r in range(3, nrows):
                boiling_range = _cell(sh, r, 0)
                if boiling_range == "" or str(boiling_range).strip() in ["", "-", "损失"]:
                    continue
                row = {
                    "crude_name": crude_name,
                    "boiling_range": str(boiling_range).strip(),
                    "yield_per_mass": _safe_float(sh, r, 1),
                    "yield_total_mass": _safe_float(sh, r, 2),
                    "yield_per_vol": _safe_float(sh, r, 3),
                    "yield_total_vol": _safe_float(sh, r, 4),
                    "density_20": _safe_float(sh, r, 5),
                }
                if ncols > 6:
                    row["pour_point"] = _safe_float(sh, r, 6)
                if ncols > 7:
                    row["acidity"] = _safe_float(sh, r, 7)
                if ncols > 8:
                    row["acid_value"] = _safe_float(sh, r, 8)
                if ncols > 9:
                    row["sulfur"] = _safe_float(sh, r, 9)
                if ncols > 10:
                    row["nitrogen"] = _safe_float(sh, r, 10)
                rows.append(row)
            return rows

    # 方案二：自动检测表头
    header_row = None
    for r in range(min(10, nrows)):
        first_cell = str(_cell(sh, r, 0)).strip()
        if "沸点范围" in first_cell or "馏分" in first_cell or "温度" in first_cell:
            header_row = r
            break
    if header_row is None:
        return []

    col_map = {}
    sub_row = header_row + 1 if header_row + 1 < nrows else None
    for c in range(ncols):
        h = str(_cell(sh, header_row, c)).strip()
        if sub_row is not None:
            h2 = str(_cell(sh, sub_row, c)).strip()
            full_h = h + h2 if h2 and h2 != h else h
        else:
            full_h = h
        if not full_h:
            continue
        if "沸点" in full_h:
            col_map["boiling_range"] = c
        elif "m/m" in full_h or ("占原油" in full_h and ("质量" in full_h or "每" in full_h)):
            if "每" in full_h or "馏" in full_h:
                col_map["yield_mass"] = c
            elif "总" in full_h:
                col_map["yield_total_mass"] = c
        elif "V/V" in full_h or ("占原油" in full_h and "体积" in full_h):
            if "每" in full_h or "馏" in full_h:
                col_map["yield_vol"] = c
            elif "总" in full_h:
                col_map["yield_total_vol"] = c
        elif "收率" in full_h and "总" in full_h:
            col_map["yield_total_mass" if "质量" in full_h or "m/m" in full_h else "yield_total_vol"] = c
        elif "收率" in full_h and ("每" in full_h or "馏" in full_h):
            col_map["yield_mass" if "质量" in full_h or "m/m" in full_h else "yield_vol"] = c
        elif "密度" in full_h:
            col_map["density"] = c
        elif "硫" in full_h:
            col_map["sulfur"] = c
        elif "氮" in full_h:
            col_map["nitrogen"] = c
        elif "酸值" in full_h:
            col_map["acid_value"] = c
        elif "粘度" in full_h or "黏度" in full_h:
            if "20" in full_h:
                col_map["viscosity_20"] = c
            elif "50" in full_h:
                col_map["viscosity_50"] = c
            elif "80" in full_h:
                col_map["viscosity_80"] = c
            elif "100" in full_h:
                col_map["viscosity_100"] = c

    if "boiling_range" not in col_map:
        return []

    for r in range(header_row + (2 if sub_row else 1), nrows):
        br = str(_cell(sh, r, col_map["boiling_range"])).strip()
        if not br or br in ["-", ""] or br == "损失":
            continue
        row = {"crude_name": crude_name, "boiling_range": br}
        row["yield_per_mass"] = _safe_float(sh, r, col_map.get("yield_mass"))
        row["yield_total_mass"] = _safe_float(sh, r, col_map.get("yield_total_mass"))
        row["yield_per_vol"] = _safe_float(sh, r, col_map.get("yield_vol"))
        row["yield_total_vol"] = _safe_float(sh, r, col_map.get("yield_total_vol"))
        row["density_20"] = _safe_float(sh, r, col_map.get("density"))
        if "sulfur" in col_map:
            row["sulfur"] = _safe_float(sh, r, col_map["sulfur"])
        if "nitrogen" in col_map:
            row["nitrogen"] = _safe_float(sh, r, col_map["nitrogen"])
        if "acid_value" in col_map:
            row["acid_value"] = _safe_float(sh, r, col_map["acid_value"])
        rows.append(row)
    return rows


# ── 原油性质 ────────────────────────────────────────────────────────
def parse_crude_properties_sheet(sheets, crude_name):
    """解析原油性质。列0=项目,列1=单位,列2=方法,列3=结果。返回 (dict, list)。"""
    sh = _get_sheet(sheets, "原油性质", "一般性质")
    if sh is None:
        return {}, []

    nrows = _nrows(sh)
    props_dict = {}
    props_list = []
    current_section = None

    for r in range(2, nrows):
        name = _cell(sh, r, 0)
        unit = _cell(sh, r, 1)
        val = _cell(sh, r, 3)

        if name == "" or name is None:
            continue
        raw_name = str(name)
        name_str = raw_name.strip()
        if not name_str or name_str in ["分析项目", "表1"] or name_str.startswith("表"):
            continue

        name_str = name_str.replace("（", "(").replace("）", ")")
        name_str = name_str.replace("　", "").strip()

        has_leading_space = raw_name != raw_name.lstrip()
        is_temp_item = bool(re.match(r'^[\d.]+℃', name_str))

        # pandas 无 ctype；错误单元格已是 NaN→''，这里不需要 ctype==5 分支
        val_str = str(val).strip() if val is not None and val != "" else ""

        if val_str in ["", "——"]:
            if not has_leading_space and not is_temp_item:
                current_section = name_str
                continue

        unit_str = ""
        if unit is not None and unit != "":
            unit_str = str(unit).strip()
            if unit_str in ["/", "-", "--", "——"]:
                unit_str = ""
            unit_str = unit_str.replace("（", "(").replace("）", ")")

        if current_section and (has_leading_space or is_temp_item):
            display_name = f"{current_section} {name_str}"
        elif current_section and not has_leading_space and not is_temp_item:
            display_name = name_str
            current_section = None
        else:
            display_name = name_str

        if val_str in ["", "/", "-", "--"]:
            props_dict[name_str] = None
            val_for_list = None
        else:
            try:
                val_float = float(val)
                props_dict[name_str] = val_float
                val_for_list = val_float
            except (ValueError, TypeError):
                props_dict[name_str] = val_str
                val_for_list = val_str

        props_list.append({"name": display_name, "unit": unit_str, "value": val_for_list})

    return props_dict, props_list


# ── 沸点范围 ────────────────────────────────────────────────────────
def parse_temp_range(boiling_range):
    if not boiling_range:
        return None
    m = re.match(r'<?\s*(\d+)\s*[～~]\s*(\d+)', boiling_range)
    if m:
        return int(m.group(1)), int(m.group(2))
    m = re.match(r'<\s*(\d+)', boiling_range)
    if m:
        return 0, int(m.group(1))
    m = re.match(r'>\s*(\d+)', boiling_range)
    if m:
        return int(m.group(1)), 9999
    return None


def calc_residue_from_distill(distill_data, crude_name):
    """无渣油 sheet 时从蒸馏数据兜底计算。"""
    residue_data = []
    for temp_range in [">350℃", ">540℃"]:
        temp_val = 350 if temp_range == ">350℃" else 540
        props = {}
        cum_mass = 0
        for d in distill_data:
            parsed = parse_temp_range(d.get("boiling_range", ""))
            if parsed:
                s, _ = parsed
                if s >= temp_val:
                    ym = d.get("yield_per_mass") or 0
                    cum_mass += ym
                    for key in ["density_20", "sulfur", "nitrogen", "acid_value", "viscosity_50", "viscosity_100"]:
                        if d.get(key) is not None:
                            props[key] = d[key]
        props["累积收率%"] = round(cum_mass, 2)
        residue_data.append({"temperature_range": temp_range, "properties": props})
    return residue_data


# ── 渣油 ────────────────────────────────────────────────────────────
def parse_residue_sheet(sheets, crude_name):
    """解析渣油。列0=项目,列1=单位,列3=>350℃,列4=>540℃,列5=推荐。"""
    sh = _get_sheet(sheets, "渣油")
    if sh is None:
        return {"residues": [], "residue_list": []}
    nrows, ncols = _nrows(sh), _ncols(sh)
    residues = []
    residue_list = []

    # 旧格式：每种温度范围一个对象
    for col_idx, label in [(3, ">350℃"), (4, ">540℃")]:
        props = {}
        current_section = None
        for r in range(2, nrows):
            name = _cell(sh, r, 0)
            val = _cell(sh, r, col_idx)
            if name == "" or name is None:
                continue
            raw_name = str(name)
            name_str = raw_name.strip().replace("（", "(").replace("）", ")")
            if not name_str or name_str.startswith("表"):
                continue

            other_val = _cell(sh, r, 4 if col_idx == 3 else 3)
            val_str = str(val).strip() if val is not None and val != "" else ""
            other_str = str(other_val).strip() if other_val is not None and other_val != "" else ""
            if val_str in ["", "——"] and other_str in ["", "——"]:
                current_section = name_str
                continue

            key = name_str
            if current_section and raw_name != raw_name.lstrip():
                key = f"{current_section} {name_str}"
            if val_str in ["", "——", "/", "-", "--"]:
                props[key] = None
            else:
                try:
                    props[key] = float(val)
                except (ValueError, TypeError):
                    props[key] = str(val).strip()
        residues.append({"temperature_range": label, "properties": props})

    # 新格式：flat list
    current_section = None
    for r in range(2, nrows):
        name = _cell(sh, r, 0)
        if name == "" or name is None:
            continue
        raw_name = str(name)
        name_str = raw_name.strip().replace("（", "(").replace("）", ")")
        if not name_str or name_str.startswith("表"):
            continue

        unit = _cell(sh, r, 1) or ""
        val_350 = _cell(sh, r, 3)
        val_540 = _cell(sh, r, 4)
        recommendation = _cell(sh, r, 5) if ncols > 5 else None

        val350_str = str(val_350).strip() if val_350 is not None and val_350 != "" else ""
        val540_str = str(val_540).strip() if val_540 is not None and val_540 != "" else ""
        if val350_str in ["-", "--"]:
            val350_str = "/"
        if val540_str in ["-", "--"]:
            val540_str = "/"

        val350_truly_empty = val350_str in ["", "——"]
        val540_truly_empty = val540_str in ["", "——"]
        if val350_truly_empty and val540_truly_empty:
            current_section = name_str
            continue

        has_leading_space = raw_name != raw_name.lstrip()
        display_name = name_str
        if current_section and has_leading_space:
            display_name = f"{current_section} {name_str}"
        elif current_section and not has_leading_space:
            current_section = None

        item = {
            "name": display_name,
            "unit": str(unit).strip() if unit else "",
            "val_350": val_350 if val350_str not in ["", "——", "/"] else None,
            "val_540": val_540 if val540_str not in ["", "——", "/"] else None,
            "recommendation": str(recommendation).strip() if recommendation and str(recommendation).strip() not in ["", "/", "-", "--"] else "",
        }
        residue_list.append(item)

    return {"residues": residues, "residue_list": residue_list}


# ── 关键馏分分类 ────────────────────────────────────────────────────
def parse_fraction_class_sheet(sheets, crude_name):
    """解析关键馏分分类（转置结构：温度范围在列头）。"""
    sh = _get_sheet(sheets, "关键馏分分类")
    if sh is None:
        return None
    nrows, ncols = _nrows(sh), _ncols(sh)
    fractions = []
    classification = ""

    for r in range(nrows):
        row_vals = [str(_cell(sh, r, c)).strip() for c in range(min(ncols, 10))]
        joined = " ".join(row_vals)
        if not classification:
            for kw in ["石蜡基原油", "中间基原油", "环烷基原油"]:
                if kw in joined:
                    classification = kw
                    break
        if not classification:
            for kw in ["石蜡基", "中间基", "环烷基"]:
                if kw in joined:
                    classification = kw + "原油"
                    break

    header_row_idx = -1
    temp_cols = []
    for r in range(min(nrows, 8)):
        candidates = []
        for c in range(ncols):
            v = str(_cell(sh, r, c)).strip()
            if re.search(r'\d{2,}\s*[～~]\s*\d{2,}', v):
                candidates.append((c, v))
        if len(candidates) >= 2:
            header_row_idx = r
            temp_cols = candidates
            break

    if not temp_cols:
        for r in range(nrows):
            first = str(_cell(sh, r, 0)).strip()
            if re.search(r'\d+\s*[～~]\s*\d+', first) or re.search(r'\d+\s*℃', first):
                row_data = {"range": first}
                for c in range(1, min(ncols, 8)):
                    v = _cell(sh, r, c)
                    if v != "" and str(v).strip():
                        try:
                            row_data[f"col{c}"] = float(v)
                        except (ValueError, TypeError):
                            row_data[f"col{c}"] = str(v).strip()
                fractions.append(row_data)
        return {"fractions": fractions, "classification": classification}

    paraffinic_by_col = {}
    intermediate_by_col = {}
    naphthenic_by_col = {}
    measured_rows = []
    SKIP_KEYWORDS = ["分类", "结论", "类别", "项目", "基属"]

    for r in range(header_row_idx + 1, nrows):
        fv = _cell(sh, r, 0)
        first = str(fv).strip() if fv is not None and fv != "" else ""
        if not first:
            continue
        col_vals = {}
        for col_idx, _ in temp_cols:
            v = _cell(sh, r, col_idx)
            if v is not None and v != "" and str(v).strip() not in ["", "/", "-", "--"]:
                col_vals[col_idx] = str(v).strip()
        if not col_vals:
            continue
        if "石蜡基" in first:
            paraffinic_by_col.update(col_vals)
        elif "中间基" in first:
            intermediate_by_col.update(col_vals)
        elif "环烷基" in first:
            naphthenic_by_col.update(col_vals)
        elif not any(kw in first for kw in SKIP_KEYWORDS):
            measured_rows.append((first, col_vals))

    for prop_name, col_vals in measured_rows:
        for col_idx, range_label in temp_cols:
            raw_val = col_vals.get(col_idx)
            if raw_val is None:
                continue
            try:
                measured = float(raw_val)
            except (ValueError, TypeError):
                measured = raw_val
            item = {"temperature_range": range_label, "property": prop_name, "measured": measured}
            if paraffinic_by_col.get(col_idx):
                item["paraffinic_std"] = paraffinic_by_col[col_idx]
            if intermediate_by_col.get(col_idx):
                item["intermediate_std"] = intermediate_by_col[col_idx]
            if naphthenic_by_col.get(col_idx):
                item["naphthenic_std"] = naphthenic_by_col[col_idx]
            fractions.append(item)

    if not fractions and any([paraffinic_by_col, intermediate_by_col, naphthenic_by_col]):
        for col_idx, range_label in temp_cols:
            if paraffinic_by_col.get(col_idx) or intermediate_by_col.get(col_idx) or naphthenic_by_col.get(col_idx):
                item = {"temperature_range": range_label, "property": "特征因数K", "measured": None}
                if paraffinic_by_col.get(col_idx):
                    item["paraffinic_std"] = paraffinic_by_col[col_idx]
                if intermediate_by_col.get(col_idx):
                    item["intermediate_std"] = intermediate_by_col[col_idx]
                if naphthenic_by_col.get(col_idx):
                    item["naphthenic_std"] = naphthenic_by_col[col_idx]
                fractions.append(item)

    return {"fractions": fractions, "classification": classification}


# ── 文字描述 ────────────────────────────────────────────────────────
def parse_text_sections(sheets, crude_name):
    """从含'评价/文本/文字'的 sheet 抽长文本段落。"""
    sections = []
    text_sheets = [s for s in sheets.keys() if "评价" in s or "文本" in s or "文字" in s]

    section_num = 1
    for sheet_name in text_sheets:
        sh = sheets.get(sheet_name)
        if sh is None:
            continue
        nrows, ncols = _nrows(sh), _ncols(sh)
        current_title = ""
        for r in range(min(nrows, 200)):
            for c in range(min(ncols, 3)):
                val = str(_cell(sh, r, c)).strip()
                if not val:
                    continue
                if any(kw in val for kw in ["原油评价", "原油性质", "总结", "概述"]):
                    current_title = val
                elif len(val) > 20:
                    sections.append({
                        "crude_name": crude_name,
                        "section_num": str(section_num),
                        "section_title": current_title,
                        "content": val,
                    })
                    section_num += 1

    if not sections:
        sections.append({
            "crude_name": crude_name,
            "section_num": "1",
            "section_title": "原油一般性质",
            "content": f"{crude_name}原油评价数据已导入系统。",
        })
    return sections


# ── 主入口 ──────────────────────────────────────────────────────────
def parse_excel(io, crude_name=None, sample_date=None, sample_point=None):
    """解析原油评价 Excel（.xls/.xlsx），返回结构化 dict（不写库）。

    io: 文件路径 / bytes / BytesIO。
    crude_name/sample_date/sample_point: 用户传入优先，封面兜底。
    """
    src = _io.BytesIO(io) if isinstance(io, (bytes, bytearray)) else io
    sheets = pd.read_excel(src, sheet_name=None, header=None)  # {name: DataFrame}

    cover = parse_cover_sheet(sheets)
    if not crude_name:
        crude_name = cover.get("crude_name", "")
    if not crude_name:
        raise ValueError("无法从Excel文件中解析原油名称，请手动输入")
    if not sample_point:
        sample_point = cover.get("sample_point", "")
    if not sample_date:
        sample_date = cover.get("sample_date", "")
    if not sample_date:
        sample_date = "00000000"

    sheet_names = list(sheets.keys())

    distill_data = parse_distillation_sheet(sheets, crude_name)
    crude_props_dict, crude_props_list = parse_crude_properties_sheet(sheets, crude_name)

    # 侧线收率
    sideline_yields = []
    for sname, cuts in SIDELINE_CUTS.items():
        cum_yield = 0
        for d in distill_data:
            parsed = parse_temp_range(d.get("boiling_range", ""))
            if parsed:
                s, e = parsed
                if s >= cuts["start"] and e <= cuts["end"]:
                    ym = d.get("yield_per_mass") or 0
                    cum_yield += ym
        sideline_yields.append({
            "sideline_name": sname,
            "cut_temp_start": cuts["start"],
            "cut_temp_end": cuts["end"],
            "cut_label": cuts["label"],
            "yield_mass_pct": round(cum_yield, 2),
        })

    # 渣油
    if "渣油" in sheet_names:
        residue_data = parse_residue_sheet(sheets, crude_name)
    else:
        residue_data = calc_residue_from_distill(distill_data, crude_name)

    # 关键馏分分类
    fraction_class = None
    if "关键馏分分类" in sheet_names:
        fraction_class = parse_fraction_class_sheet(sheets, crude_name)
    if not fraction_class and crude_props_dict:
        fraction_class = {
            "fractions": {
                "密度(20℃)": crude_props_dict.get("密度(20℃)"),
                "硫含量(μg/g)": crude_props_dict.get("硫含量(μg/g)"),
                "酸值(mgKOH/g)": crude_props_dict.get("酸值(mgKOH/g)"),
                "残炭(质量分数)": crude_props_dict.get("残炭(质量分数)"),
                "原油类别": crude_props_dict.get("原油类别", ""),
            },
            "classification": crude_props_dict.get("原油类别", ""),
        }

    text_sections = parse_text_sections(sheets, crude_name)

    return {
        "crude_name": crude_name,
        "sample_date": sample_date,
        "sample_point": sample_point,
        "distillation": distill_data,
        "crude_props_dict": crude_props_dict,
        "crude_props_list": crude_props_list,
        "sideline_yields": sideline_yields,
        "residue": residue_data,
        "fraction_class": fraction_class,
        "text_sections": text_sections,
    }

# ── 节点入口：下载 → 解析 → 输出预览 + 结构化JSON（不写库）──
def main(args: dict) -> dict:
    import requests

    file_url = (args.get("file_url") or "").strip()
    crude_name = (args.get("crude_name") or "").strip() or None
    sample_date = (args.get("sample_date") or "").strip() or None
    sample_point = (args.get("sample_point") or "").strip() or None

    if not file_url:
        return {"markdown": "未收到上传文件，请先上传原油评价 Excel（.xls/.xlsx）。",
                "parsed": "", "ok": "no"}
    try:
        resp = requests.get(file_url, timeout=60); resp.raise_for_status()
        content = resp.content
    except Exception as e:
        return {"markdown": f"文件下载失败：{type(e).__name__} {e}", "parsed": "", "ok": "no"}
    try:
        r = parse_excel(content, crude_name=crude_name, sample_date=sample_date, sample_point=sample_point)
    except ValueError as e:
        return {"markdown": f"解析失败：{e}（请重新上传并说明原油名称）", "parsed": "", "ok": "no"}
    except Exception as e:
        return {"markdown": f"Excel 解析出错：{type(e).__name__} {e}", "parsed": "", "ok": "no"}

    sp = r["sample_point"] or "-"
    md = (
