        f"确认无误请回复「确认入库」；如需修改，回复如：原油名称=渤中25-1 采样日期=20251011 采样点=连安湖"
    )
    return {"markdown": md, "parsed": json.dumps(r, ensure_ascii=False, default=str), "ok": "yes"}

